
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_mn15_l_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_mn15_l", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.032552149288864e-01, -2.123101549316149e-01, -2.235206702324489e-01, -2.356877159095269e-01, -2.446493133372753e-01, -2.399902954488115e-01, -2.020167959241485e-01, -1.111991851919167e-01, 8.378703288712453e-03, 8.176551738184609e-02, 7.556247348934846e-02, -9.349996819184782e-02, -4.644292883008905e-02, -3.296167432566761e-02, 1.028692765549381e-02, 3.714300759838385e-02, -4.960576630566768e-03, -1.867678178445914e-02, -6.042374704325095e-03, -8.665425244350569e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


